(() => {
const image=new Image(),tiles=[];image.onload=()=>{const c=document.createElement('canvas');c.width=image.width;c.height=image.height;const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(image,0,0);for(let i=0;i<4;i++){const sx=i%2*image.width/2,sy=Math.floor(i/2)*image.height/2,w=Math.floor(image.width/2),h=Math.floor(image.height/2),a=cx.getImageData(sx,sy,w,h).data;let l=w,t=h,r=0,b=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(a[(y*w+x)*4+3]>35){l=Math.min(l,x);t=Math.min(t,y);r=Math.max(r,x);b=Math.max(b,y)}tiles[i]={sx:sx+l,sy:sy+t,w:r-l+1,h:b-t+1}}window.gameDebug?.render()};
function draw(c,i,x,y,w,h){const s=tiles[i];if(s)c.drawImage(image,s.sx,s.sy,s.w,s.h,x-w/2,y-h/2,w,h)}
window.renderDecor=(c,scene)=>{for(const d of scene.decor){if(d.kind==='bench')draw(c,1,d.x+.5,d.y+.5,1.35,.68);else if(d.kind==='rug'){c.fillStyle='#743f38';c.fillRect(d.x-.5,d.y-.5,d.w,d.h);c.strokeStyle='#b39861';c.lineWidth=.035;c.strokeRect(d.x-.38,d.y-.38,d.w-.24,d.h-.24);c.strokeStyle='#b398613d';c.beginPath();c.moveTo(d.x-.15,d.y+.1);c.lineTo(d.x+.45,d.y+.7);c.lineTo(d.x+1.05,d.y+.1);c.stroke()}}};
window.renderTorches=scene=>{const layer=document.getElementById('torches');layer.replaceChildren();for(const l of scene.lights.filter(l=>l.id!=='altar')){const el=document.createElement('div');el.className='torch';el.style.left=l.x*64+'px';el.style.top=l.y*64+'px';el.style.setProperty('--phase',-l.phase+'s');const c=document.createElement('canvas');c.width=80;c.height=120;draw(c.getContext('2d'),3,40,60,32,80);el.append(c);layer.append(el)}};image.src='assets/cartoon-decor.png';
})();
